"""Habla con las APIs de los proveedores.

Una función por proveedor. Todas devuelven lo mismo: texto, tokens de entrada
y tokens de salida. Así el resto del programa no sabe con quién está hablando
ni le hace falta saberlo.
"""

import os
from pathlib import Path

import requests

CARPETA = Path(__file__).parent
ESPERA_MAXIMA = 120  # segundos que aguantamos antes de darnos por vencidos

# Qué variable de entorno guarda la clave de cada proveedor.
# La clave NUNCA se escribe aquí: solo el nombre del cajón donde vive.
VARIABLE_DE_CLAVE = {
    "openai": "OPENAI_API_KEY",
    "google": "GOOGLE_API_KEY",
    "anthropic": "ANTHROPIC_API_KEY",
}


def cargar_env():
    """Lee el archivo .env y copia sus valores a las variables de entorno."""
    archivo = CARPETA / ".env"
    if not archivo.exists():
        return
    for linea in archivo.read_text(encoding="utf-8").splitlines():
        linea = linea.strip()
        if not linea or linea.startswith("#") or "=" not in linea:
            continue
        nombre, valor = linea.split("=", 1)
        nombre = nombre.strip()
        valor = valor.strip().strip('"').strip("'")
        # Si la variable ya existe en el sistema, mandan las del sistema
        if nombre and valor and not os.environ.get(nombre):
            os.environ[nombre] = valor


def clave_de(proveedor):
    """Devuelve la clave del proveedor, o cadena vacía si no la tienes."""
    variable = VARIABLE_DE_CLAVE.get(proveedor, "")
    clave = os.environ.get(variable, "").strip()
    # Si sigue puesto el texto de ejemplo, es como no tener clave
    if clave.startswith("pega-aqui"):
        return ""
    return clave


def _comprobar(respuesta, proveedor):
    """Si la API contesta con un error, lo cuenta en cristiano y para."""
    if respuesta.status_code != 200:
        raise RuntimeError(
            f"{proveedor} respondió {respuesta.status_code}: {respuesta.text[:300]}"
        )
    return respuesta.json()


def _openai(modelo, prompt, clave):
    datos = _comprobar(requests.post(
        "https://api.openai.com/v1/chat/completions",
        headers={"Authorization": f"Bearer {clave}"},
        json={
            "model": modelo,
            "messages": [{"role": "user", "content": prompt}],
            "max_tokens": 900,  # tope de respuesta, para que no se dispare el coste
        },
        timeout=ESPERA_MAXIMA,
    ), "openai")
    uso = datos["usage"]
    return {
        "texto": datos["choices"][0]["message"]["content"],
        "tokens_entrada": uso["prompt_tokens"],
        "tokens_salida": uso["completion_tokens"],
    }


def _anthropic(modelo, prompt, clave):
    datos = _comprobar(requests.post(
        "https://api.anthropic.com/v1/messages",
        headers={"x-api-key": clave, "anthropic-version": "2023-06-01"},
        json={
            "model": modelo,
            "max_tokens": 900,
            "messages": [{"role": "user", "content": prompt}],
        },
        timeout=ESPERA_MAXIMA,
    ), "anthropic")
    trozos = [b.get("text", "") for b in datos["content"] if b.get("type") == "text"]
    uso = datos["usage"]
    return {
        "texto": "".join(trozos),
        "tokens_entrada": uso["input_tokens"],
        "tokens_salida": uso["output_tokens"],
    }


def _google(modelo, prompt, clave):
    url = (
        "https://generativelanguage.googleapis.com/v1beta/models/"
        f"{modelo}:generateContent"
    )
    datos = _comprobar(requests.post(
        url,
        headers={"x-goog-api-key": clave},
        json={"contents": [{"parts": [{"text": prompt}]}]},
        timeout=ESPERA_MAXIMA,
    ), "google")
    partes = datos["candidates"][0].get("content", {}).get("parts", [])
    texto = "".join(p.get("text", "") for p in partes)
    uso = datos.get("usageMetadata", {})
    # Los tokens que el modelo gasta pensando se facturan como salida,
    # y vienen en un campo aparte. Si no los sumas, el coste te sale corto.
    salida = uso.get("candidatesTokenCount", 0) + uso.get("thoughtsTokenCount", 0)
    return {
        "texto": texto,
        "tokens_entrada": uso.get("promptTokenCount", 0),
        "tokens_salida": salida,
    }


FUNCIONES = {"openai": _openai, "anthropic": _anthropic, "google": _google}


def llamar(proveedor, modelo, prompt):
    """Manda el prompt al modelo y devuelve texto + tokens."""
    if proveedor not in FUNCIONES:
        raise RuntimeError(f"No conozco el proveedor '{proveedor}'")
    clave = clave_de(proveedor)
    if not clave:
        raise RuntimeError(f"Falta la clave de {proveedor} en el archivo .env")
    return FUNCIONES[proveedor](modelo, prompt, clave)


def listar(proveedor):
    """Pide a la API la lista de modelos que puedes usar hoy."""
    clave = clave_de(proveedor)
    if not clave:
        return []
    if proveedor == "openai":
        datos = _comprobar(requests.get(
            "https://api.openai.com/v1/models",
            headers={"Authorization": f"Bearer {clave}"},
            timeout=ESPERA_MAXIMA), "openai")
        return sorted(m["id"] for m in datos.get("data", []))
    if proveedor == "anthropic":
        datos = _comprobar(requests.get(
            "https://api.anthropic.com/v1/models",
            headers={"x-api-key": clave, "anthropic-version": "2023-06-01"},
            timeout=ESPERA_MAXIMA), "anthropic")
        return sorted(m["id"] for m in datos.get("data", []))
    if proveedor == "google":
        datos = _comprobar(requests.get(
            "https://generativelanguage.googleapis.com/v1beta/models",
            headers={"x-goog-api-key": clave},
            timeout=ESPERA_MAXIMA), "google")
        return sorted(m["name"].replace("models/", "") for m in datos.get("models", []))
    return []
